          "viewing_task": "<ol><li><strong>[01:10] Recall:</strong> Which two natural resources beneath and across Britain's landscape powered early industrial mills and furnaces?</li><li><strong>[03:15] Explain:</strong> Explain how breakthroughs in coal-fired steam power and wrought-iron production allowed factories and railways to multiply rapidly.</li><li><strong>[05:30] Challenge:</strong> Was Britain's industrial take-off driven more by local inventors and ironmasters, or by global trade and empire?</li></ol>",
          "model_answer": "<ol><li><strong>Recall:</strong> Fast-flowing river water (for waterwheels) and shallow, abundant seams of coal alongside iron ore.</li><li><strong>Explain:</strong> Steam engines pumped water from deep mines and freed mills from river valleys, while wrought-iron puddling and rolling produced cheap, strong iron for machinery, bridges, warships, and rails.</li><li><strong>Challenge:</strong> Both worked together: British engineers like Newcomen, Watt, and Henry Cort built the machines and iron furnaces, while imperial ports, captive colonial markets, and Atlantic capital financed mass production.</li></ol>"
