      "short_tab_title": "1. Blake & Iron Furnaces",
      "literary_mode": "verbatim_literature",
      "provenance_tier": "verbatim_literature",
      "source_type": "period_verse",
      "source_type_label": "Romantic Poetry (1794–1804) & Ironworks Context",
      "is_primary": true,
      "is_adapted": false,
      "book_title": "Dark Satanic Mills: William Blake’s London (1794) & The Fires of Industrial Britain",
      "author": "William Blake (Songs of Experience, 1794; Milton Preface, 1804)",
      "provenance_note": "Verbatim stanzas from William Blake’s 'London' (Songs of Experience, 1794) and his 1804 Preface to Milton ('And did those feet in ancient time'), framed with Shropshire and Hampshire ironmaking context.",
      "author_context": "Between 1750 and 1804, coal-fired blast furnaces at Coalbrookdale, James Watt’s rotary steam engines, and Henry Cort’s puddling furnaces at Funtley turned rural Britain into the world’s iron powerhouse. Walking through smoke-darkened streets in 1794 and 1804, poet and engraver William Blake gave the Industrial Revolution its most haunting literary phrase: 'dark Satanic Mills'.",
      "cover_image": "/images/ks3_ind/ind_l1_s0_coalbrookdale_by_night_1801.jpg",
      "cover_caption": "Philipp Jakob de Loutherbourg, Coalbrookdale by Night (1801, Science Museum London): Coke-fired Shropshire blast furnaces illuminating the wooded Severn Gorge day and night.",
      "vocabVault": [
        {
          "term": "Charter’d",
          "pronunciation": "CHAR-terd",
          "def": "Mapped out, owned, and controlled for commercial profit—Blake’s protest that even the River Thames seemed bought and sold."
        },
        {
          "term": "Mind-Forg’d Manacles",
          "pronunciation": "MYND-forjd MAN-uh-kulz",
          "def": "Blake’s metaphor comparing invisible social rules, factory discipline, and poverty to heavy iron handcuffs forged in a furnace."
        },
        {
          "term": "Puddling Furnace",
          "pronunciation": "PUD-ling FUR-niss",
          "def": "Henry Cort’s 1783 Hampshire coal-fired furnace that burned impurities out of brittle pig iron to make tough wrought iron."
        },
        {
          "term": "Satanic Mills",
          "pronunciation": "suh-TAN-ik MILZ",
          "def": "Blake’s famous 1804 phrase contrasting green rural England with roaring, smoke-blackened steam mills and ironworks."
        }
      ],
      "extract": "Across late eighteenth-century Britain, coal fires replaced quiet oak woodlands. Coke blast furnaces roared at Coalbrookdale in Shropshire, while Henry Cort’s puddling hearths in Hampshire stirred white-hot iron for the Royal Navy. Walking beside the smoky Thames in 1794, poet and engraver William Blake etched London onto copper plates.\n\n<div class=\"reading-stanza\">I wander thro’ each charter’d street,<br>Near where the charter’d Thames does flow.<br>And mark in every face I meet<br>Marks of weakness, marks of woe.</div>\n\n<div class=\"reading-stanza\">In every cry of every Man,<br>In every Infant’s cry of fear,<br>In every voice, in every ban,<br>The mind-forg’d manacles I hear.</div>\n\nTen years later, James Watt’s rotary steam engines had freed factories from quiet river valleys and packed smoky towns with workers. In his 1804 preface to Milton, Blake asked a haunting question.\n\n<div class=\"reading-stanza\">And did the Countenance Divine,<br>Shine forth upon our clouded hills?<br>And was Jerusalem builded here,<br>Among these dark Satanic Mills?</div>\n\nVisitors riding toward Shropshire’s iron gorge after dark understood Blake’s awe and dread. Crimson furnace flames lit the night clouds while heavy steam hammers shook the ground beneath their boots. Rivers of glowing molten metal poured hissing and smoking into beds of damp sand. Cheap British wrought iron armed Nelson’s warships and bridged deep rivers—yet green rural England had changed forever.",
      "parent_discussion": [
        {
          "question": "Why does William Blake use a metalworking word—'mind-forg’d manacles' (handcuffs)—in his 1794 poem London?",
          "answer": "Just as ironmasters forged real chains and bars in coal furnaces, Blake felt harsh industrial poverty and strict laws chained working people’s minds and lives."
        },
        {
          "question": "Look at de Loutherbourg’s 1801 painting Coalbrookdale by Night alongside Blake’s phrase 'dark Satanic Mills': why did coal and iron amaze yet frighten witnesses?",
          "answer": "Coke blast furnaces and puddling hearths created thrilling national wealth and naval iron, yet drowned wooded valleys in 24-hour smoke, fire, and exhausting labour."
        },
        {
          "question": "How had James Watt’s steam engine and Henry Cort’s puddling furnace changed where and how British iron and goods were made by 1804?",
          "answer": "Coal replaced scarce oak charcoal and steam replaced river waterwheels, letting huge mills and ironworks run non-stop in smoky towns."
        }
      ],
