      "extract": "Sent north from a London workhouse at age seven, orphan Robert Blincoe never forgot the terror of the cotton mill.\n\n\"At five o’clock each morning, the clanging bell tore us from our straw beds. Any child who arrived two minutes late felt the overlooker’s heavy leather strap across their shoulders. As young scavengers, we had to creep right underneath the heavy spinning mules. While iron wheels whirled rapidly overhead, we swept up flying cotton dust from the oily floorboards. Inside rooms heated to eighty degrees so threads would not snap, we worked fourteen hours a day on sour oatcakes. Often a tired child fell asleep standing up, and unguarded cogs tore off fingers before the engine stopped.\"\n\nWhen MPs published such reports from mills and coal pits, poet Elizabeth Barrett Browning shamed Victorian readers in 1843 with The Cry of the Children.\n\n<div class=\"reading-stanza\">For, all day, we drag our burden tiring,<br>Through the coal-dark, underground.<br>Or, all day, we drive the wheels of iron<br>In the factories, round and round.</div>\n\nMoved by survivor voices like Blincoe and Matthew Crabtree, Parliament passed the 1833 Factory Act. Children under nine were banned from textile mills, and four paid inspectors began checking the factories.",
