      "extract": "In 1842, Edwin Chadwick proved that a labourer in smoky Manchester lived an average of only seventeen years. Farmworkers in rural Rutland lived more than twice as long, reaching thirty-eight. Visiting Lancashire in 1854, novelist Charles Dickens painted industrial \"Coketown\" in Hard Times.\n\n\"It was a town of red brick, or of brick that would have been red if the smoke and ashes had allowed it. As matters stood, it was a town of unnatural red and black. It was a town of machinery and tall chimneys, out of which interminable serpents of smoke trailed themselves for ever and ever, and never got uncoiled.\n\nIt had a black canal in it, and a river that ran purple with ill-smelling dye. Vast piles of building full of windows rattled and trembled all day long. Inside them, the piston of the steam-engine worked monotonously up and down, like the head of an elephant in a state of melancholy madness.\n\nIt contained several large streets all very like one another, and many small streets still more like one another. People equally like one another went in and out at the same hours, with the same sound upon the same pavements, to do the same work.\"",
