      "extract": "By candlelight in a small London workshop in 1838, cabinetmaker William Lovett dipped his pen in ink and wrote six plain rules. Six years before, factory masters had cheered the 1832 Reform Act for ending empty \"rotten boroughs\" like grassy Old Sarum. Yet five in every six adult men still owned too little house property to vote. Lovett’s People’s Charter called for votes for every man, secret ballots, and wages for MPs so a poor weaver could sit in Westminster.\n\nTen years later, on the rainy morning of 10 April 1848, fear gripped Britain’s rulers. Ministers sent young Queen Victoria to safety on the Isle of Wight. Aged Waterloo hero the Duke of Wellington lined the Thames bridges with troops and cannon. South of the river on Kennington Common, thousands of peaceful Chartists stood beneath silk banners as cameraman William Kilburn took their picture.\n\nTo spare lives at the bridges, leader Feargus O’Connor sent the crowd home in peace and packed their giant rolled petition into three horse-drawn cabs. MPs laughed at joke names like \"Pugnose\" and voted the Charter down again. Yet Lovett outlived the jeers. Starting with Pontefract’s locked wooden ballot box in 1872, five of his Six Points became British law.",
